// Drop mentions whose author is not in DISCORD_ALLOWED_AUTHORS (comma-separated user IDs).
// If the env var is unset or empty, all mentions pass (backwards compatible).
const raw = $env.DISCORD_ALLOWED_AUTHORS || '';
const allowed = raw.split(',').map(s => s.trim()).filter(Boolean);
if (allowed.length === 0) return $input.all();
return $input.all().filter(item => allowed.includes(String(item.json.authorId || '')));

// Load RSS sources from mounted config file (./rss_sources.json -> /home/node/rss_sources.json)
// Edit that file to add/remove/toggle feeds — no workflow change needed.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buffer || buffer.length === 0) {
  throw new Error('rss_sources.json is missing or empty at /home/node/rss_sources.json');
}

let parsed;
try {
  parsed = JSON.parse(buffer.toString('utf8'));
} catch (e) {
  throw new Error('rss_sources.json is not valid JSON: ' + e.message);
}

if (!parsed || !Array.isArray(parsed.sources)) {
  throw new Error('rss_sources.json must contain a top-level "sources" array');
}

const sources = parsed.sources.filter(s => s && s.active && s.url);
if (sources.length === 0) {
  throw new Error('rss_sources.json has no active sources with a url');
}

console.log(`📡 Loaded ${sources.length} active RSS sources`);
return sources.map(s => ({
  json: { url: s.url, name: s.name, category: s.category, priority: s.priority }
}));

// Filter by date (last 2 days)                                                                                        
 const cutoff = new Date(Date.now() - 2 * 24 * 60 * 60 * 1000);                                                         
 const filtered = [];                                                                                                   

 for (const item of $input.all()) {                                                                                     
   try {                                                                                                              
     if (!item.json) continue;                                                                                          

     const url = item.json.link || item.json.url || '';                                                                 
     const title = item.json.title || '';                                                                             

     // Skip if no URL or title                                                                                       
     if (!url || url.trim() === '' || !title || title.trim() === '') {
       continue;                                                                                                        
     }

     // Parse publication date                                                                                          
     let pubDate = null;
     if (item.json.pubDate) {                                                                                           
       pubDate = new Date(item.json.pubDate);                                                                         
     } else if (item.json.isoDate) {                                                                                    
       pubDate = new Date(item.json.isoDate);
     }                                                                                                                  

     // Skip items with no parseable date - prevents leaks via default-to-now
     if (!pubDate || isNaN(pubDate.getTime())) {
       continue;
     }

     // Only filter by date - AI will filter by relevance                                                               
     const isRecent = pubDate >= cutoff;

     if (isRecent) {                                                                                                  
       let source = 'Unknown';                                                                                          
       try {                                                                                                            
         source = new URL(url).hostname.replace('www.', '');
       } catch (e) {                                                                                                    
         source = item.json.creator || item.json.author || 'Unknown';                                                 
       }                                                                                                                

       filtered.push({                                                                                                  
         json: {                                                                                                      
           url: url.trim(),
           title: title,                                                                                                
           description: (item.json.description || item.json.contentSnippet || '').substring(0, 500),
           content: (item.json.content || item.json['content:encoded'] || '').substring(0, 1000),                       
           source: source,                                                                                            
           published_at: pubDate.toISOString()                                                                          
         }                                                                                                            
       });                                                                                                              
     }                                                                                                                
   } catch (error) {
     continue;
   }
 }

 return filtered;

// Categorize, add source_type, and prepare for insert
const categories = {
  '🧠 LLM': ['llm', 'gpt', 'claude', 'mistral', 'gemini', 'chatgpt', 'language model', 'large language'],
  '📚 RAG': ['rag', 'retrieval', 'embedding', 'vector', 'semantic search'],
  '🎨 Vision': ['image', 'diffusion', 'dall-e', 'midjourney', 'stable diffusion', 'vision', 'computer vision', 'image generation'],
  '🤖 Agents': ['agent', 'autonomous', 'agentic', 'workflow', 'swarm', 'multi-agent'],
  '💻 Coding': ['code', 'copilot', 'coding', 'cursor', 'github copilot', 'devin', 'programming', 'developer'],
  '🔬 Research': ['research', 'paper', 'arxiv', 'publication', 'study', 'breakthrough', 'academic']
};

const items = $input.all();
const output = [];

for (const item of items) {
  try {
    // Skip if no url or title
    if (!item.json.url || !item.json.title) {
      continue;
    }

    // Categorize by content
    const text = (
      (item.json.title || '') + ' ' + 
      (item.json.description || '') + ' ' + 
      (item.json.content || '')
    ).toLowerCase();

    let category = '🤖 AI General';
    for (const [cat, keywords] of Object.entries(categories)) {
      if (keywords.some(kw => text.includes(kw))) {
        category = cat;
        break;
      }
    }

    // Determine source_type based on source domain and URL
    const source = item.json.source || 'Unknown';
    const url = (item.json.url || '').toLowerCase();
    const sourceLower = source.toLowerCase();
    let source_type = 'Other';

    // Reddit Communities - Explicit Reddit domain check
    if (sourceLower.includes('reddit.com') || url.includes('reddit.com')) {
      source_type = 'Reddit Communities';
    }
    // Company Blogs - Official company blogs and announcements
    else if (
      sourceLower.includes('openai.com') || url.includes('openai.com') ||
      sourceLower.includes('anthropic.com') || url.includes('anthropic.com') ||
      sourceLower.includes('huggingface.co') || url.includes('huggingface.co') ||
      sourceLower.includes('blog.google') || url.includes('blog.google') ||
      sourceLower.includes('deepmind.google') || url.includes('deepmind.google') ||
      sourceLower.includes('ai.meta.com') || url.includes('ai.meta.com') ||
      sourceLower.includes('stability.ai') || url.includes('stability.ai') ||
      sourceLower.includes('cohere.com') || url.includes('cohere.com') ||
      sourceLower.includes('mistral.ai') || url.includes('mistral.ai')
    ) {
      source_type = 'Company Blogs';
    }
    // Tech News - match only on source domain (not body keywords) to avoid false positives
    else if (
      /(?:techcrunch\.com|hnrss\.org|news\.ycombinator\.com|github\.com|github\.io)/.test(sourceLower + ' ' + url)
    ) {
      source_type = 'Tech News';
    }

    // Add category, source_type and pass through (truncated to fit DB column widths)
    output.push({
      json: {
        url: String(item.json.url).slice(0, 2048),
        title: String(item.json.title).slice(0, 1000),
        description: (item.json.description || '').slice(0, 2000),
        content: (item.json.content || '').slice(0, 4000),
        source: String(source).slice(0, 200),
        source_type: String(source_type).slice(0, 80),
        category: String(category).slice(0, 80),
        published_at: item.json.published_at || new Date().toISOString()
      }
    });
  } catch (error) {
    // Skip problematic items
    continue;
  }
}

return output;

const items = $input.all();
const urls = items.map(item => item.json.url).filter(url => url && url.trim() !== '');

if (urls.length === 0) {
  return [];
}

return [{
  json: {
    urls: urls,
    items: items.map(i => i.json)
  }
}];

const originalItems = $('Collect URLs for DB check').first().json.items;
const dbResult = $input.all();
const existingURls = new Set(dbResult.map(res => res.json.url).filter(Boolean));

const newArticles = originalItems.filter(item => !existingURls.has(item.url));

console.log(`total : ${originalItems.length}`);
console.log(`Already in db : ${existingURls.size}`);
console.log(`new : ${newArticles.length}`);

if (newArticles.length === 0) {
  return [];
} else {
  return newArticles.map(item => ({json: item}));
}

// Prepare SQL-safe values by escaping single quotes
const items = $input.all();
const output = [];

for (const item of items) {
  try {
    // Function to escape single quotes for SQL
    const sqlEscape = (str) => {
      if (!str) return '';
      return String(str).replace(/'/g, "''");
    };

    output.push({
      json: {
        url: sqlEscape(item.json.url),
        title: sqlEscape(item.json.title),
        description: sqlEscape(item.json.description),
        content: sqlEscape(item.json.content),
        source: sqlEscape(item.json.source),
        source_type: sqlEscape(item.json.source_type),
        category: item.json.category,
        published_at: item.json.published_at
      }
    });
  } catch (error) {
    continue;
  }
}

return output;

