// ===================================
// PARSE GEMINI AVEC MAX_TOKENS PRÉCOCE
// ===================================

const items = $input.all();
const articles = $('Escape SQL Values').all();

console.log(`📥 Traitement de ${items.length} articles`);

const output = [];
let maxTokensCount = 0;
let tooShortCount = 0;
let successCount = 0;

for (let i = 0; i < items.length; i++) {
  const article = articles[i]?.json || {};

  let score = 0;
  let confidence = 0;
  let reason = 'Parsing error';
  let aiTag = '';
  let aiSummary = '';
  let aiTakeaway = '';

  try {
    const candidate = items[i].json.candidates[0];
    const finishReason = candidate.finishReason;
    const text = candidate.content.parts[0].text;

    // Vérifier si MAX_TOKENS
    if (finishReason === 'MAX_TOKENS') {
      maxTokensCount++;

      // Si le texte est trop court (< 20 chars), impossible de parser
      if (text.length < 20) {
        tooShortCount++;
        console.log(`⚠️  Article ${i}: MAX_TOKENS avec texte trop court (${text.length} chars) - SKIP`);
        reason = 'MAX_TOKENS - Response too short to parse';
        // On laisse confidence=0 pour filtrer cet article

      } else {
        // Tenter de parser quand même
        const clean = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

        try {
          const parsed = JSON.parse(clean);
          score = parsed.score || 0;
          confidence = parsed.confidence || 50; // Confiance moyenne
          reason = 'Parsed despite MAX_TOKENS';
          successCount++;
        } catch {
          // Échec de parsing mais on garde une trace
          reason = 'MAX_TOKENS - Could not parse incomplete JSON';
          confidence = 0; // Sera filtré
        }
      }

    } else {
      // Cas normal : STOP
      const clean = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
      const parsed = JSON.parse(clean);

      score = parsed.score || 0;
      confidence = parsed.confidence || 0;
      reason = parsed.reason || 'OK';
      aiTag = parsed.tag || parsed.ai_tag || '';
      aiSummary = parsed.summary || parsed.ai_summary || '';
      aiTakeaway = parsed.takeaway || parsed.ai_takeaway || '';

      // Valider
      score = Math.max(0, Math.min(100, Number(score) || 0));
      confidence = Math.max(0, Math.min(100, Number(confidence) || 0));

      successCount++;
    }

  } catch (error) {
    console.log(`❌ Article ${i}: ${error.message}`);
  }

  output.push({
    json: {
      ...article,
      gemini_score: score,
      gemini_confidence: confidence,
      gemini_reason: reason,
      ai_tag: aiTag,
      ai_summary: aiSummary,
      ai_takeaway: aiTakeaway
    }
  });
}

// Filtrage
const filtered = output.filter(item => item.json.gemini_confidence >= 85);

console.log(`
┌─────────────────────────────────────────────┐
│         📊 PARSING STATISTICS               │
├─────────────────────────────────────────────┤
│ Total articles:              ${output.length.toString().padStart(3)}         │
│ ⚠️  MAX_TOKENS:               ${maxTokensCount.toString().padStart(3)}         │
│ 🚫 Too short (< 20 chars):   ${tooShortCount.toString().padStart(3)}         │
│ ✅ Successfully parsed:       ${successCount.toString().padStart(3)}         │
│ 🎯 Pass filter (≥ 85):        ${filtered.length.toString().padStart(3)}         │
├─────────────────────────────────────────────┤
│ ⚠️  WARNING: ${maxTokensCount} articles hit MAX_TOKENS │
│    Gemini stopped generating immediately!   │
└─────────────────────────────────────────────┘
`);

return filtered;

// Split by source_type, sort by score desc, keep top-N per group, tag each item with webhook metadata.
const items = $input.all().map(i => i.json);

const groups = {
  'Tech News':          { webhook: $env.DISCORD_WEBHOOK_TECH_NEWS, color: 15844367, label: '📰 Tech News IA',          defaultTag: '',   limit: 10 },
  'Company Blogs':      { webhook: $env.DISCORD_WEBHOOK_COMPANIES, color: 10181046, label: '💬 Companies Blog IA',     defaultTag: '',   limit: 10 },
  'Reddit Communities': { webhook: $env.DISCORD_WEBHOOK_REDDIT,    color: 10181046, label: '💬 Reddit Communities IA', defaultTag: '',   limit: 10 },
  'Other':              { webhook: $env.DISCORD_WEBHOOK_OTHERS,    color: 7506394,  label: '🔗 Other Sources IA',       defaultTag: '💡', limit: 10 }
};

const byGroup = {};
for (const it of items) {
  const key = groups[it.source_type] ? it.source_type : 'Other';
  (byGroup[key] ||= []).push(it);
}

const out = [];
for (const [key, list] of Object.entries(byGroup)) {
  list.sort((a, b) => (b.gemini_score || 0) - (a.gemini_score || 0));
  const meta = groups[key];
  list.slice(0, meta.limit).forEach(a => {
    out.push({ json: { ...a, _group: key, _webhook: meta.webhook, _color: meta.color, _label: meta.label, _default_tag: meta.defaultTag } });
  });
}
return out;

